package com.iankoulski.problems.leetcode;

import java.util.*;

public class WordBreak1 {

    public boolean wordBreak(String s, String[] wordDict) {
        int n = s.length();
        boolean[][] dp = new boolean[n][n];
        Arrays.fill(dp, true);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (s.charAt(i) == ' ') {
                    dp[i][j] = false;
                } else {
                    for (int k = 0; k < j; k++) {
                        if (wordDict[k].equals(s.substring(i, j + 1))) {
                            dp[i][j] = dp[i][k] || dp[k + 1][j];
                        }
                    }
                }
            }
        }

        return dp[n - 1][n - 1];
    }

