import parser.TokenTypes;

public class Tokenizer {

    private final Map<TokenTypes, Token> tokens;

    public Tokenizer(Map<TokenTypes, Token> tokens) {
        this.tokens = tokens;
    }

    public Token nextToken() throws Exception {
        if (tokens.isEmpty()) {
            throw new Exception("No token available");
        }

        Token token = tokens.values().iterator().next();
        tokens.remove(token.getType());

        return token;
    }

    public TokenTypes getTokenType(Token token) {
        return token.getType();
    }

    public void printTokens() {
        for (Token token : tokens.values()) {
            System.out.println(token);
        }
    }
}

