                        }
                    } else { // 向右
                        if (obj.index == n) {
                            iterator.remove();
                        } else {
                            obj.index = obj.index + 1;
                        }
                    }
                }
            }

            if (objList.size() != 0) {
                for (Obj ele : objList) {
                    if (ele.hasChange) {
                        ele.hasChange = false;
                    }
                }
                result = result + 1;
            } else {
                return result;
            }
        }

        return result;
    }

    private void meetPro(ArrayList<Obj> objList, Obj obj) {
        // 已经处理过的不能再次处理
        if (!obj.hasChange) {
            // 遍历查找是否有符合的相遇元素
            for (Obj ele : objList) {
                if (obj.des == 0) { // 向左的找向右元素
                    if (!ele.hasChange && ele.index == obj.index - 1 && ele.des == 1) {
                        ele.des = 0;
                        ele.hasChange = true;
                        obj.des = 1;
                        obj.hasChange = true;
                        break;
                    }
                } else {
                    if (!ele.hasChange && ele.index == obj.index + 1 && ele.des == 0) {
                        ele.des = 1;
                        ele.hasChange = true;
                        obj.des = 0;
                        obj.hasChange = true;
                        break;
                    }
                }
            }
        }
    }

    private static class Obj {
        Integer index;
        Integer des; // 0 向左(-1) , 1 向右(+1)
        boolean hasChange = false;

        public Obj(Integer index, Integer des) {
            this.index = index;
            this.des = des;
        }
    }
}

