public class MaxSumAfterPartition {

    // Define a function to calculate the maximum sum of subarrays of length at most K.
    // The function should return an array of integers representing the maximum sum of subarrays of length K.

    public int[] maxSumAfterPartition(int[] A, int K) {
        int n = A.length;
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            result[i] = Math.max(A[i], A[i + 1] - K + 1);
        }
        return result;
    }

    public static void main(String[] args) {
        MaxSumAfterPartition partitioner = new MaxSumAfterPartition();
        int[] A = {1, 2, 3, 4, 5};
        int K = 2;
        int[] maxSum = partitioner.maxSumAfterPartition(A, K);
